begin;

-- CLASS_INTEGRATION_STRICT: class:fighter
-- CLASS_INTEGRATION_STRICT: class:cleric
-- CLASS_PACKAGE_TEST: tests/classTextNarrationAudit.test.ts
-- Text-only GM adjudication pass. This migration changes payload.description only.
-- It intentionally does not alter resources, actions, formulas, effects, costs, grants or CE availability.

create or replace function private.patch_builtin_feature_rule_text(
  p_campaign_id uuid,
  p_catalog_key text,
  p_level integer,
  p_source_key text,
  p_description text
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_template uuid;
begin
  select id into v_template
  from public.rule_templates
  where campaign_id=p_campaign_id
    and is_active
    and catalog_key=p_catalog_key
  order by version desc
  limit 1;

  if v_template is null then return; end if;

  update public.rule_template_levels l
  set mechanics=coalesce((
    select jsonb_agg(
      case
        when m->>'type'='grant'
          and m->>'target'='feature'
          and m->>'sourceKey'=p_source_key
          then jsonb_set(m,'{payload,description}',to_jsonb(p_description),true)
        else m
      end
      order by ord
    )
    from jsonb_array_elements(coalesce(l.mechanics,'[]'::jsonb)) with ordinality q(m,ord)
  ),'[]'::jsonb)
  where l.template_id=v_template
    and l.level=p_level;
end;
$$;

create or replace function private.apply_gm_rule_text_fighter_cleric(p_campaign_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  -- FIGHTER -----------------------------------------------------------------
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'class:fighter',1,'fighting-style',$r$Выберите один талант категории «Боевой стиль», требованиям которого соответствуете, и получите его эффекты постоянно. Каждый раз, когда получаете новый уровень Воина, можете заменить выбранный этим умением Боевой стиль другим подходящим Боевым стилем. Само умение не тратит ресурс; ограничения конкретного стиля указаны в его карточке.$r$);

  perform private.patch_builtin_feature_rule_text(p_campaign_id,'class:fighter',1,'second-wind',$r$Бонусным действием потратьте 1 использование Второго дыхания и восстановите 1к10 + уровень Воина HP. На 1 уровне запас равен 2 использованиям, на 4 — 3, на 10 — 4. После короткого отдыха возвращается 1 потраченное использование; после долгого отдыха возвращается весь запас.$r$);

  perform private.patch_builtin_feature_rule_text(p_campaign_id,'class:fighter',1,'weapon-mastery',$r$Выберите 3 вида простого или воинского оружия, которыми владеете: вы можете применять свойство Мастерства каждого выбранного вида оружия. Число выбранных видов становится 4 на 4 уровне Воина, 5 на 10 и 6 на 16. После каждого долгого отдыха можно заменить один выбранный вид оружия другим подходящим видом. Само применение свойства Мастерства не расходует отдельный классовый ресурс, если его собственное правило не говорит обратного.$r$);

  perform private.patch_builtin_feature_rule_text(p_campaign_id,'class:fighter',2,'action-surge',$r$В свой ход можете потратить 1 использование Всплеска действий и немедленно получить ещё одно действие в этом же ходу. Это дополнительное действие нельзя использовать для действия Магия. До 17 уровня доступно 1 использование, с 17 уровня — 2, но не более одного Всплеска действий за ход. Все использования возвращаются после короткого или долгого отдыха.$r$);

  perform private.patch_builtin_feature_rule_text(p_campaign_id,'class:fighter',2,'tactical-mind',$r$Когда вы провалили проверку характеристики, можете потратить применение Второго дыхания не на лечение, а на Тактическое мышление: бросьте 1к10 и прибавьте результат к этой проверке, после чего ГМ заново определяет успех. Если итог всё равно не достигает Сл проверки, применение Второго дыхания по этому правилу не расходуется. Это прямое исключение из обычного правила списания ресурса.$r$);

  perform private.patch_builtin_feature_rule_text(p_campaign_id,'class:fighter',5,'extra-attack',$r$Когда в свой ход совершаете действие Атака, можете выполнить 2 атаки вместо 1. Каждая атака выбирает цель и разрешается отдельно обычным способом. Эта способность пассивна и не расходует ресурс.$r$);

  perform private.patch_builtin_feature_rule_text(p_campaign_id,'class:fighter',5,'tactical-shift',$r$Когда бонусным действием активируете Второе дыхание и тратите его использование, в рамках того же бонусного действия можете переместиться на расстояние до половины своей Скорости. Это перемещение не провоцирует атаки по возможности. Дополнительного ресурса сверх уже потраченного Второго дыхания не требуется.$r$);

  perform private.patch_builtin_feature_rule_text(p_campaign_id,'class:fighter',9,'indomitable',$r$После провала спасброска можете потратить 1 использование Неукротимого и перебросить этот спасбросок, добавив к новому результату свой уровень Воина. Новый результат обязателен, даже если он хуже прежнего. Доступно 1 использование на 9 уровне, 2 на 13 и 3 на 17; весь запас возвращается после долгого отдыха.$r$);

  perform private.patch_builtin_feature_rule_text(p_campaign_id,'class:fighter',9,'tactical-master',$r$Каждый раз, когда совершаете атаку оружием, для которого умеете применять свойство Мастерства, до разрешения эффекта Мастерства можете заменить обычное свойство этого оружия на Push, Sap или Slow только для этой атаки. Бросок атаки и урон не меняются сами по себе; затем применяется выбранное свойство по его собственному правилу. Ресурс не тратится.$r$);

  perform private.patch_builtin_feature_rule_text(p_campaign_id,'class:fighter',11,'two-extra-attacks',$r$Когда в свой ход совершаете действие Атака, можете выполнить 3 атаки вместо 1. Каждая атака выбирает цель и разрешается отдельно. Эта способность заменяет значение Дополнительной атаки Воина 5 уровня, а не добавляет ещё две атаки поверх него.$r$);

  perform private.patch_builtin_feature_rule_text(p_campaign_id,'class:fighter',13,'studied-attacks',$r$Если ваша атака по существу промахнулась, вы получаете преимущество на следующую атаку по этому же существу, совершённую до конца вашего следующего хода. После этой следующей атаки преимущество от способности исчезает независимо от её результата. Ресурс не тратится.$r$);

  perform private.patch_builtin_feature_rule_text(p_campaign_id,'class:fighter',17,'action-surge',$r$Запас Всплеска действий увеличивается до 2 использований. В свой ход одно использование даёт ещё одно действие, которое нельзя использовать для действия Магия. По-прежнему нельзя применять Всплеск действий более одного раза за ход. Все использования возвращаются после короткого или долгого отдыха.$r$);

  perform private.patch_builtin_feature_rule_text(p_campaign_id,'class:fighter',17,'indomitable',$r$Запас Неукротимого увеличивается до 3 использований. После провала спасброска потратьте 1 использование, перебросьте спасбросок и добавьте уровень Воина к новому результату; новый результат обязателен. Все использования возвращаются после долгого отдыха.$r$);

  perform private.patch_builtin_feature_rule_text(p_campaign_id,'class:fighter',20,'three-extra-attacks',$r$Когда в свой ход совершаете действие Атака, можете выполнить 4 атаки вместо 1. Каждая атака разрешается отдельно. Эта способность заменяет прежнее число атак от Дополнительной атаки, а не складывается с ним.$r$);

  -- CLERIC BASE --------------------------------------------------------------
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'class:cleric',2,'channel-divinity',$r$Божественный канал имеет общий запас: 2 использования на 2 уровне Жреца, 3 на 6 и 4 на 18. После короткого отдыха возвращается 1 потраченное использование, после долгого — весь запас. Если эффект Божественного канала требует спасбросок, используется Сл заклинаний Жреца. На 2 уровне доступны два способа расхода. «Божественная искра»: магическим действием потратьте 1 использование, выберите другое видимое существо в 30 футах и бросьте 1к8 + модификатор Мудрости; либо восстановите цели столько HP, либо заставьте её совершить спасбросок Телосложения: при провале она получает столько некротического или сияющего урона на ваш выбор, при успехе — половину, округляя вниз. Кость Искры становится 2к8 на 7 уровне, 3к8 на 13 и 4к8 на 18. «Изгнание нежити»: магическим действием потратьте 1 использование; каждая выбранная вами нежить в 30 футах совершает спасбросок Мудрости. При провале она Испугана и Недееспособна на 1 минуту и в свои ходы старается удалиться от вас как можно дальше. Для конкретной цели эффект заканчивается раньше, если она получает урон; весь эффект также прекращается, если вы становитесь Недееспособны или умираете.$r$);

  -- ARCANA DOMAIN ------------------------------------------------------------
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:arcana-domain',1,'arcana-domain-l1-1',$r$Вы получаете владение навыком Магия и выбираете 2 заговора из списка Волшебника. Для вас эти заговоры считаются заговорами Жреца и используют Мудрость как заклинательную характеристику. Заклинания домена, выдаваемые прогрессией подкласса, всегда считаются подготовленными и не занимают число обычных подготовленных заклинаний.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:arcana-domain',2,'channel-divinity-arcane-abjuration-l2-1',$r$Действием потратьте 1 использование Божественного канала и выберите одного небожителя, элементаля, фею или исчадие в пределах 30 футов, которое видите. Цель совершает спасбросок Мудрости против Сл заклинаний Жреца. При провале она изгнана вашим священным запретом на 1 минуту или пока не получит урон: она старается удалиться от вас, не может добровольно приблизиться к вам, не совершает реакции и обычно тратит действие на Рывок либо попытку освободиться от удерживающего эффекта; если двигаться некуда, использует Уклонение. С 5 уровня, если КО цели не выше текущего порога Уничтожения нежити Жреца, провал вместо обычного изгнания отправляет её на родной план на 1 минуту, если она не находится там изначально.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:arcana-domain',6,'spell-breaker-l6-1',$r$Когда заклинанием 1 уровня или выше восстанавливаете HP союзнику, можете одновременно закончить на нём одно заклинание по своему выбору. Уровень снимаемого заклинания должен быть не выше уровня ячейки, потраченной на лечащее заклинание. Отдельного действия или ресурса не требуется.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:arcana-domain',8,'potent-spellcasting-l8-1',$r$Когда заговор Жреца наносит урон, добавьте модификатор Мудрости к одному броску урона этого заговора. Это пассивный эффект и не расходует ресурс.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:arcana-domain',8,'blessed-strikes-l8-2',$r$Если этот вариант выбран вместо другого боевого усиления домена, один раз на каждом своём ходу, когда вы попадаете атакой оружием или наносите урон заговором Жреца, можете нанести одной цели дополнительно 1к8 сияющего урона. Ресурс не тратится; ограничение — один раз за ваш ход.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:arcana-domain',17,'arcane-mastery-l17-1',$r$Выберите по одному заклинанию Волшебника 6, 7, 8 и 9 уровня. Выбранные заклинания становятся для вас заклинаниями домена Жреца: они всегда подготовлены, используют Мудрость и ячейки Жреца обычным способом. Выбор совершается при получении способности; сама способность не создаёт дополнительных ячеек.$r$);

  -- DEATH DOMAIN -------------------------------------------------------------
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:death-domain',1,'death-domain-l1-1',$r$Вы получаете владение воинским оружием и изучаете один заговор школы Некромантии из любого списка заклинаний; для вас он считается заговором Жреца. Когда вы накладываете заговор Некромантии, который обычно выбирает только одно существо, можете вместо этого выбрать двух существ, если они находятся не дальше 5 футов друг от друга и обе цели находятся в обычной дальности заговора.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:death-domain',2,'channel-divinity-touch-of-death-l2-1',$r$Когда попадаете по существу рукопашной атакой, можете потратить 1 использование Божественного канала сразу после попадания. Цель получает дополнительный некротический урон, равный 5 + удвоенный уровень Жреца. Спасброска нет; ресурс расходуется на сработавшее попадание.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:death-domain',6,'inescapable-destruction-l6-1',$r$Некротический урон ваших заклинаний Жреца и способностей Божественного канала игнорирует сопротивление некротическому урону. Иммунитет эта способность не снимает. Эффект пассивный.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:death-domain',8,'divine-strike-l8-1',$r$Один раз на каждом своём ходу, когда попадаете атакой оружием, можете добавить к урону этой атаки 1к8 некротического урона. С 14 уровня дополнительный урон становится 2к8. Ресурс не тратится.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:death-domain',8,'blessed-strikes-l8-2',$r$Если этот вариант выбран вместо другого боевого усиления домена, один раз на каждом своём ходу после попадания оружием или нанесения урона заговором Жреца нанесите одной цели дополнительно 1к8 сияющего урона. Отдельного ресурса нет.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:death-domain',17,'improved-reaper-l17-1',$r$Когда накладываете заклинание Некромантии 1–5 уровня, которое обычно выбирает только одно существо, можете выбрать второе существо в пределах дальности заклинания, если обе цели находятся не дальше 5 футов друг от друга. Если заклинание расходует материальный компонент, необходимо предоставить такой компонент для каждой цели. Ячейка заклинания тратится одна.$r$);

  -- FORGE DOMAIN -------------------------------------------------------------
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:forge-domain',1,'forge-domain-l1-1',$r$Вы получаете владение тяжёлой бронёй и инструментами кузнеца. После долгого отдыха выберите один немагический доспех либо одно немагическое простое или воинское оружие, которого касаетесь. До следующего долгого отдыха или вашей смерти предмет становится магическим: доспех получает +1 к КД, а оружие — +1 к броскам атаки и урона. Одновременно так может быть усилен только один предмет.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:forge-domain',2,'channel-divinity-artisan-s-blessing-l2-1',$r$Потратьте 1 использование Божественного канала и проведите непрерывный часовой ритуал, выкладывая металл стоимостью, равной создаваемому предмету. В конце ритуала создайте один простой металлический предмет стоимостью не более 100 зм; это может быть оружие, доспех, боеприпасы, инструмент или другой предмет, если в нём есть необходимое количество металла. Можно воссоздать металлическую копию существующего предмета, если его стоимость не выше 100 зм. Использованный металл расходуется.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:forge-domain',6,'soul-of-the-forge-l6-1',$r$Вы получаете сопротивление урону огнём. Пока носите тяжёлую броню, ваш КД дополнительно увеличивается на 1. Оба эффекта пассивны и не требуют ресурса.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:forge-domain',8,'divine-strike-l8-1',$r$Один раз на каждом своём ходу после попадания атакой оружием можете добавить 1к8 урона огнём. С 14 уровня дополнительный урон становится 2к8. Ресурс не тратится.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:forge-domain',8,'blessed-strikes-l8-2',$r$Если выбран этот альтернативный вариант усиления, один раз на каждом своём ходу после попадания оружием или нанесения урона заговором Жреца нанесите одной цели дополнительно 1к8 сияющего урона. Ресурс не тратится.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:forge-domain',17,'saint-of-forge-and-fire-l17-1',$r$Вы получаете иммунитет к урону огнём. Кроме того, пока носите тяжёлую броню, получаете сопротивление дробящему, колющему и рубящему урону от немагических атак. Эффекты пассивны.$r$);

  -- GRAVE DOMAIN 2025 --------------------------------------------------------
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:grave-domain',3,'grave-domain-l3-1',$r$Вы получаете три связанных правила. «Зов смерти»: один раз за ход, когда заклинанием или атакой наносите урон существу, у которого уже не все HP, оно получает ещё 1к4 некротического урона; с 11 уровня — 1к6. «Возвращение к жизни»: «Уход за умирающим» можно накладывать бонусным действием; если заклинанием или Божественным каналом лечите существо с 0 HP, вместо бросков костей лечения берите максимальный результат каждой кости. «Путь к могиле»: бонусным действием потратьте 1 Божественный канал и прокляните видимое существо в 30 футах до начала вашего следующего хода; у него помеха на атаки и спасброски. Когда вы или видимый вами союзник попадает по проклятой цели атакой, можете без действия закончить проклятие и добавить к этой атаке некротический или сияющий урон, равный уровню Жреца.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:grave-domain',6,'sentinel-at-death-s-door-l6-1',$r$Когда вы или окровавленное существо, которое видите в пределах 60 футов, получает попадание атакой, можете реакцией уменьшить урон этой атаки вдвое, округляя вниз. Если попадание было критическим, все дополнительные эффекты, зависящие именно от критического попадания, отменяются. Использований равно модификатору Мудрости, минимум 1; весь запас возвращается после долгого отдыха.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:grave-domain',17,'divine-reaper-l17-1',$r$Способность даёт два эффекта. «Усиленная некромантия»: когда накладываете заклинание Некромантии 5 уровня или ниже, выбирающее одну цель, либо заклинание из списка домена Могилы, можете потратить 1 Божественный канал и выбрать вторую цель в дальности заклинания; дорогие или расходуемые материальные компоненты нужны отдельно для каждой цели. «Хранитель душ»: когда враг умирает в 60 футах от вас и вы не Недееспособны, вы или видимое существо в 60 футах восстанавливает HP, равные удвоенному уровню Жреца. После этого Хранитель душ возвращается после короткого или долгого отдыха; можно без действия восстановить его раньше, потратив ячейку 6 уровня или выше.$r$);

  -- KNOWLEDGE DOMAIN 2025 ----------------------------------------------------
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:knowledge-domain',3,'knowledge-domain-l3-1',$r$Вы получаете владение одним видом ремесленных инструментов и выбираете 2 навыка из Магии, Истории, Природы и Религии; в этих двух навыках получаете Экспертизу. Кроме того, «Магия разума» позволяет магическим действием потратить 1 использование Божественного канала, выбрать подготовленное заклинание школы Прорицания из списка заклинаний домена Знания и сотворить его частью того же действия без ячейки и без материальных компонентов.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:knowledge-domain',6,'unfettered-mind-l6-1',$r$Вы получаете телепатию на 60 футов и при её использовании можете одновременно связаться с числом существ до модификатора Мудрости, минимум 1. Также получаете владение спасбросками Интеллекта; если уже владеете ими, выберите другой спасбросок, которым ещё не владеете, и получите владение им. Ресурс не тратится.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:knowledge-domain',17,'divine-foreknowledge-l17-1',$r$Бонусным действием активируйте божественное предвидение на 1 час. Всё это время у вас преимущество на все испытания к20: атаки, проверки характеристик и спасброски. После применения способность недоступна до долгого отдыха. Без действия можно восстановить её использование раньше, потратив ячейку заклинания 6 уровня или выше.$r$);

  -- LIGHT DOMAIN 2024 --------------------------------------------------------
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:light-domain',3,'light-domain-l3-1',$r$На 3 уровне домен даёт два активных правила. «Сияние рассвета»: магическим действием потратьте 1 Божественный канал; вся магическая Тьма в 30-футовой эманации от вас рассеивается, а каждое выбранное вами существо в этой области совершает спасбросок Телосложения. При провале оно получает 2к10 + уровень Жреца сияющего урона, при успехе — половину. «Защитная вспышка»: когда видимое вами существо в 30 футах совершает атаку, можете реакцией дать этой атаке помеху до определения попадания. Использований Вспышки равно модификатору Мудрости, минимум 1; весь запас возвращается после долгого отдыха.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:light-domain',6,'improved-warding-flare-l6-1',$r$Все использования Защитной вспышки теперь возвращаются после короткого или долгого отдыха. Кроме того, каждый раз, когда используете Защитную вспышку, можете дать цели спровоцировавшей атаки временные HP, равные 2к6 + модификатор Мудрости. Дополнительного действия или ресурса не требуется.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:light-domain',17,'corona-of-light-l17-1',$r$Магическим действием создайте вокруг себя ауру солнечного света на 1 минуту; её можно прекратить без действия. Вы излучаете яркий свет на 60 футов и тусклый ещё на 30. Враги в области яркого света совершают с помехой спасброски против вашего Сияния рассвета и против ваших заклинаний, наносящих урон огнём или сиянием. Использований равно модификатору Мудрости, минимум 1; весь запас возвращается после долгого отдыха.$r$);

  -- NATURE DOMAIN ------------------------------------------------------------
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:nature-domain',1,'nature-domain-l1-1',$r$Вы изучаете один заговор Друида; для вас он считается заговором Жреца и использует Мудрость. Также получаете владение одним навыком на выбор: Уход за животными, Природа или Выживание, и владение тяжёлой бронёй. Эти эффекты постоянны.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:nature-domain',2,'channel-divinity-charm-animals-and-plants-l2-1',$r$Действием потратьте 1 Божественный канал. Каждый зверь или растение в пределах 30 футов, которое видит вас, совершает спасбросок Мудрости против Сл заклинаний Жреца. При провале существо очаровано вами на 1 минуту либо пока не получит урон. Каждая цель бросает отдельно.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:nature-domain',6,'dampen-elements-l6-1',$r$Когда вы или существо в пределах 30 футов получает урон кислотой, холодом, огнём, электричеством или громом, можете реакцией дать этой цели сопротивление именно к этому срабатыванию урона. Сопротивление применяется до расчёта окончательного урона и заканчивается сразу после него. Ресурс не тратится.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:nature-domain',8,'divine-strike-l8-1',$r$Один раз на каждом своём ходу после попадания атакой оружием можете добавить 1к8 урона холодом, огнём или электричеством на выбор. С 14 уровня дополнительный урон становится 2к8. Ресурс не тратится.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:nature-domain',8,'blessed-strikes-l8-2',$r$Если выбран этот альтернативный вариант, один раз на каждом своём ходу после попадания оружием или нанесения урона заговором Жреца нанесите одной цели дополнительно 1к8 сияющего урона. Ресурс не тратится.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:nature-domain',17,'master-of-nature-l17-1',$r$Пока существа остаются очарованы вашим «Очарованием животных и растений», бонусным действием можете дать устную команду каждому из них, определив, что оно будет делать в свой следующий ход. Команда не требует отдельного спасброска, но само очарование по-прежнему заканчивается по своим обычным условиям.$r$);

  -- ORDER DOMAIN -------------------------------------------------------------
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:order-domain',1,'order-domain-l1-1',$r$Вы получаете владение тяжёлой бронёй и одним навыком на выбор: Запугивание или Убеждение. «Глас власти»: когда заклинанием 1 уровня или выше тратите ячейку и выбираете целью союзника, один союзник, затронутый этим заклинанием, может сразу после заклинания реакцией совершить одну атаку оружием по существу по вашему выбору, которое вы видите. Если заклинание затронуло нескольких союзников, реакцию получает только один из них.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:order-domain',2,'channel-divinity-order-s-demand-l2-1',$r$Действием потратьте 1 Божественный канал. Каждое выбранное вами существо в 30 футах, которое видит или слышит вас, совершает спасбросок Мудрости. При провале оно очаровано вами до конца вашего следующего хода либо пока не получит урон. В момент провала можете также потребовать, чтобы цель немедленно уронила всё, что держит.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:order-domain',6,'embodiment-of-the-law-l6-1',$r$Когда накладываете заклинание школы Очарования с обычным временем накладывания «действие», можете вместо действия наложить его бонусным действием. Использований равно модификатору Мудрости, минимум 1; весь запас возвращается после долгого отдыха. Ячейка и другие компоненты заклинания расходуются как обычно.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:order-domain',8,'divine-strike-l8-1',$r$Один раз на каждом своём ходу после попадания атакой оружием можете добавить 1к8 психического урона. С 14 уровня дополнительный урон становится 2к8. Ресурс не тратится.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:order-domain',8,'blessed-strikes-l8-2',$r$Если выбран этот альтернативный вариант, один раз на каждом своём ходу после попадания оружием или нанесения урона заговором Жреца нанесите одной цели дополнительно 1к8 сияющего урона. Ресурс не тратится.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:order-domain',17,'order-s-wrath-l17-1',$r$Когда наносите существу дополнительный психический урон Божественным ударом, пометьте его до начала вашего следующего хода. Следующий союзник, который до этого момента попадёт по помеченной цели атакой, наносит ей дополнительно 2к8 психического урона, после чего метка заканчивается. На одной цели одновременно учитывается только ближайшее такое срабатывание.$r$);

  -- PEACE DOMAIN -------------------------------------------------------------
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:peace-domain',1,'peace-domain-l1-1',$r$Вы получаете владение одним навыком на выбор: Проницательность, Выступление или Убеждение. «Ободряющая связь»: действием выберите число согласных существ в пределах 30 футов до вашего бонуса мастерства, включая себя. Связь длится 10 минут или пока не используете способность снова. Пока связанное существо находится в 30 футах хотя бы от одного другого связанного существа, один раз за ход оно может добавить 1к4 к атаке, проверке характеристики или спасброску после броска к20. Использований Связи равно бонусу мастерства; весь запас возвращается после долгого отдыха.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:peace-domain',2,'channel-divinity-balm-of-peace-l2-1',$r$Действием потратьте 1 Божественный канал и переместитесь на расстояние до своей Скорости, не провоцируя атаки по возможности. Во время этого перемещения, когда впервые проходите в пределах 5 футов от существа, можете восстановить ему 2к6 + модификатор Мудрости HP. Одно и то же существо можно вылечить этим применением только один раз.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:peace-domain',6,'protective-bond-l6-1',$r$Когда существо, связанное вашей Ободряющей связью, собирается получить урон, другое связанное существо в пределах 30 футов от него может реакцией телепортироваться в свободное место в 5 футах от первой цели. Телепортировавшееся существо получает весь спровоцировавший урон вместо первоначальной цели. Связь должна быть активна; дополнительный ресурс не тратится.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:peace-domain',8,'potent-spellcasting-l8-1',$r$Когда заговор Жреца наносит урон, добавьте модификатор Мудрости к одному броску урона этого заговора. Эффект пассивный.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:peace-domain',8,'blessed-strikes-l8-2',$r$Если выбран этот альтернативный вариант, один раз на каждом своём ходу после попадания оружием или нанесения урона заговором Жреца нанесите одной цели дополнительно 1к8 сияющего урона. Ресурс не тратится.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:peace-domain',17,'expansive-bond-l17-1',$r$Дальность Защитной связи увеличивается с 30 до 60 футов. Когда связанное существо телепортируется реакцией Защитной связи и принимает чужой урон, оно получает сопротивление всему урону до конца текущего хода, включая спровоцировавший урон. Остальные условия Ободряющей и Защитной связи не меняются.$r$);

  -- TEMPEST DOMAIN -----------------------------------------------------------
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:tempest-domain',1,'tempest-domain-l1-1',$r$Вы получаете владение воинским оружием и тяжёлой бронёй. «Гнев бури»: когда видимое вами существо в пределах 5 футов попадает по вам атакой, можете реакцией заставить его совершить спасбросок Ловкости. При провале оно получает 2к8 урона электричеством или громом на ваш выбор, при успехе — половину. Использований равно модификатору Мудрости, минимум 1; весь запас возвращается после долгого отдыха.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:tempest-domain',2,'channel-divinity-destructive-wrath-l2-1',$r$Когда должны бросить кости урона электричеством или громом, можете потратить 1 использование Божественного канала и вместо броска взять максимально возможный результат каждой кости этого урона. Способность не добавляет новых костей и не меняет тип урона; она только максимизирует уже определённые кости.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:tempest-domain',6,'thunderbolt-strike-l6-1',$r$Когда наносите существу Большого размера или меньше урон электричеством, можете оттолкнуть его от себя на расстояние до 10 футов. Спасброска и ресурса нет; вы сами выбираете, применять ли отталкивание.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:tempest-domain',8,'divine-strike-l8-1',$r$Один раз на каждом своём ходу после попадания атакой оружием можете добавить 1к8 урона громом. С 14 уровня дополнительный урон становится 2к8. Ресурс не тратится.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:tempest-domain',8,'blessed-strikes-l8-2',$r$Если выбран этот альтернативный вариант, один раз на каждом своём ходу после попадания оружием или нанесения урона заговором Жреца нанесите одной цели дополнительно 1к8 сияющего урона. Ресурс не тратится.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:tempest-domain',17,'stormborn-l17-1',$r$Пока вы не находитесь под землёй и не внутри помещения, получаете Скорость полёта, равную текущей Скорости ходьбы. Полёт не требует действия или ресурса и прекращается, когда перестаёт выполняться условие местности.$r$);

  -- TRICKERY DOMAIN 2024 -----------------------------------------------------
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:trickery-domain',3,'trickery-domain-l3-1',$r$На 3 уровне получаете два правила. «Благословение обманщика»: магическим действием выберите себя или согласное существо в 30 футах; до вашего следующего долгого отдыха либо до следующего использования этого умения цель имеет преимущество на проверки Ловкости (Скрытность). «Вызов двойника»: бонусным действием потратьте 1 Божественный канал и создайте неосязаемую визуальную копию себя в видимом свободном месте в 30 футах. Она существует 1 минуту, пока вы не уберёте её без действия или не станете Недееспособны. Заклинания можно накладывать так, словно вы находитесь в пространстве копии, но используются ваши чувства. Если вы и копия одновременно в 5 футах от существа, которое видит копию, ваши атаки по нему имеют преимущество. Бонусным действием копию можно передвинуть до 30 футов в видимое свободное место, остающееся в 120 футах от вас.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:trickery-domain',6,'trickster-s-transposition-l6-1',$r$Каждый раз, когда бонусным действием создаёте копию через Вызов двойника или передвигаете уже существующую копию, можете в рамках того же бонусного действия телепортироваться, поменявшись с ней местами. Дополнительное использование Божественного канала при обычном перемещении уже созданной копии не тратится.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:trickery-domain',17,'improved-duplicity-l17-1',$r$Вызов двойника получает два улучшения. «Общее отвлечение»: вы и ваши союзники совершаете с преимуществом атаки по существу, находящемуся в пределах 5 футов от копии. «Исцеляющая иллюзия»: когда копия заканчивает существование, выберите себя или существо в пределах 5 футов от неё; выбранная цель восстанавливает HP, равные вашему уровню Жреца.$r$);

  -- TWILIGHT DOMAIN ----------------------------------------------------------
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:twilight-domain',1,'twilight-domain-l1-1',$r$Вы получаете владение воинским оружием и тяжёлой бронёй. Ваше тёмное зрение имеет дальность 300 футов. Действием можете поделиться этим тёмным зрением на 1 час с числом согласных существ до модификатора Мудрости, минимум 1, которые находятся в 10 футах от вас в момент применения; повторно бесплатно это можно сделать после долгого отдыха либо раньше, потратив ячейку заклинания. Кроме того, действием можете коснуться существа, включая себя, и дать ему преимущество на следующий бросок инициативы; благословение заканчивается после этого броска или когда вы дадите его другой цели.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:twilight-domain',2,'channel-divinity-twilight-sanctuary-l2-1',$r$Действием потратьте 1 Божественный канал и создайте вокруг себя 30-футовую сферу тусклого света на 1 минуту; сфера движется вместе с вами и заканчивается, если вы Недееспособны или умираете. Когда существо, включая вас, заканчивает ход внутри сферы, можете выбрать один эффект для него: дать временные HP, равные 1к6 + уровень Жреца, либо закончить на нём состояние Очарован или Испуган. Для каждого существа решение принимается в конце его хода.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:twilight-domain',6,'steps-of-night-l6-1',$r$Пока находитесь в тусклом свете или темноте, бонусным действием можете получить Скорость полёта, равную Скорости ходьбы, на 1 минуту. Использований равно бонусу мастерства; весь запас возвращается после долгого отдыха. Если условия освещения меняются после активации, уже полученный полёт продолжается до конца длительности.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:twilight-domain',8,'divine-strike-l8-1',$r$Один раз на каждом своём ходу после попадания атакой оружием можете добавить 1к8 сияющего урона. С 14 уровня дополнительный урон становится 2к8. Ресурс не тратится.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:twilight-domain',8,'blessed-strikes-l8-2',$r$Если выбран этот альтернативный вариант, один раз на каждом своём ходу после попадания оружием или нанесения урона заговором Жреца нанесите одной цели дополнительно 1к8 сияющего урона. Ресурс не тратится.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:twilight-domain',17,'twilight-shroud-l17-1',$r$Пока активно ваше Сумеречное святилище, вы и союзники внутри его сферы имеете половинное укрытие: +2 к КД и спасброскам Ловкости против эффектов, для которых укрытие применимо. Дополнительного действия или ресурса не требуется.$r$);

  -- WAR DOMAIN 2024 ----------------------------------------------------------
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:war-domain',3,'war-domain-l3-1',$r$На 3 уровне получаете два боевых правила. «Направленный удар»: когда вы или существо в 30 футах промахивается атакой, можете потратить 1 Божественный канал и дать этому броску +10, после чего ГМ заново проверяет попадание; если помогаете другому существу, дополнительно тратите реакцию, для собственной атаки реакция не нужна. «Жрец войны»: бонусным действием совершите одну атаку оружием или Безоружный удар. Использований Жреца войны равно модификатору Мудрости, минимум 1; весь запас возвращается после короткого или долгого отдыха.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:war-domain',6,'war-god-s-blessing-l6-1',$r$Вместо траты ячейки можете потратить 1 использование Божественного канала, чтобы сотворить «Щит веры» или «Духовное оружие». Заклинание, сотворённое так, не требует Концентрации и длится 1 минуту; оно заканчивается раньше, если вы снова сотворите то же заклинание, станете Недееспособны или умрёте. Все остальные параметры заклинания действуют обычно.$r$);
  perform private.patch_builtin_feature_rule_text(p_campaign_id,'subclass:cleric:war-domain',17,'avatar-of-battle-l17-1',$r$Вы постоянно имеете сопротивление дробящему, колющему и рубящему урону независимо от того, магический источник урона или нет. Действие и ресурс не требуются.$r$);

  -- Re-attach Voss comments only where they are absent. Existing comments are preserved.
  update public.rule_templates t
  set mechanics=private.audit_feature_mechanics_text(t.mechanics),
      choices=private.audit_feature_choices_text(t.choices),
      rules_meta=coalesce(t.rules_meta,'{}'::jsonb)||jsonb_build_object(
        'gm_adjudication_text',true,
        'ce_role','resource_bookkeeping',
        'resource_spend_policy','spend_on_activation_unless_feature_explicitly_refunds',
        'feature_author','Рейнар Восс',
        'feature_author_voice',jsonb_build_array('циничный','саркастичный','чёрный юмор')
      ),
      updated_at=now()
  where t.campaign_id=p_campaign_id
    and t.is_active
    and (t.catalog_key='class:fighter' or t.catalog_key like 'subclass:fighter:%' or t.catalog_key='class:cleric' or t.catalog_key like 'subclass:cleric:%');

  update public.rule_template_levels l
  set mechanics=private.audit_feature_mechanics_text(l.mechanics),
      choices=private.audit_feature_choices_text(l.choices)
  where exists(
    select 1 from public.rule_templates t
    where t.id=l.template_id
      and t.campaign_id=p_campaign_id
      and t.is_active
      and (t.catalog_key='class:fighter' or t.catalog_key like 'subclass:fighter:%' or t.catalog_key='class:cleric' or t.catalog_key like 'subclass:cleric:%')
  );
end;
$$;

create or replace function private.apply_gm_rule_text_fighter_cleric_after_campaign()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform private.apply_gm_rule_text_fighter_cleric(new.id);
  return new;
end;
$$;

drop trigger if exists zzzzzzzzzzzz_campaigns_gm_rule_text_fighter_cleric on public.campaigns;
create trigger zzzzzzzzzzzz_campaigns_gm_rule_text_fighter_cleric
after insert on public.campaigns
for each row execute function private.apply_gm_rule_text_fighter_cleric_after_campaign();

do $$
declare r record;
begin
  for r in select id from public.campaigns loop
    perform private.apply_gm_rule_text_fighter_cleric(r.id);
  end loop;
end $$;

commit;
